132	function useCollisions(): Register {
133	  const labels = useRef(new Map<string, { el: HTMLElement; prio: number }>());
134	  const tick = useRef(0);
135	  const register = useCallback<Register>((key, prio) => (el) => {
136	    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
137	  }, []);
