142	      const r = el.getBoundingClientRect();
143	      if (!r.width) continue;
144	      const hit = prio < FOCUS && placed.some((q) => r.left < q.right + 3 && r.right > q.left - 3 && r.top < q.bottom + 2 && r.bottom > q.top - 2);
145	      el.toggleAttribute("data-collide", hit);
