187	    return areaLayout(st, themeOf).map(({ a, at }) => ({
188	      a, ring: [at[0] * p.spread, at[1] * p.spread, at[2] * p.spread] as Vec3, plane: [at[0], at[1] + RISE_DY, at[2]] as Vec3,
