192	
193	  /* domain groups on a ring at plane height, one phyllotaxis disc each, in the payload's domain order */
194	  const groups = useMemo(() => {
195	    const order = [...p.data.domains.map((d) => d.key), ...new Set(p.reqs.map((r) => r.domain))].filter((k, i, xs) => xs.indexOf(k) === i);
196	    const present = order.filter((k) => p.reqs.some((r) => r.domain === k));
197	    const n = present.length || 1;
198	    return present.map((key, i) => {
199	      const ang = (i / n) * Math.PI * 2 - Math.PI / 2 + Math.PI / n;
200	      const c: Vec3 = [RC * Math.cos(ang), PLANE_Y, RC * Math.sin(ang)];
201	      const members = p.reqs.filter((r) => r.domain === key);
202	      const rad = SPACING * Math.sqrt(members.length);
203	      return { key, label: p.data.domains.find((d) => d.key === key)?.label ?? key, c, ang, members,
