230	      });
231	    }
232	    return out;
233	  }, [p.reqs, p.data.zones, p.frame, p.carScale, groups, diamonds, areaIdx]);
234	
235	  /* the moves */
236	  useEffect(() => { if (stage === "car") p.anim.current.flyWait = p.reduced ? 0 : FLY_DELAY; }, [stage, p.reduced, p.anim]);
237	  // whatever was under the pointer moves away with the stage change
238	  useEffect(() => { setView({ hover: null, hoverPos: null, hoverArea: null, hoverDomain: null }); }, [stage]);
239	  const landed = useRef(false);
240	  const dGroups = useRef<(THREE.Group | null)[]>([]);
241	  const dMats = useRef<(THREE.MeshBasicMaterial | null)[]>([]);
242	  const dLabels = useRef<(HTMLElement | null)[]>([]);
243	  const nGroups = useRef<(THREE.Group | null)[]>([]);
244	  const nEls = useRef<(HTMLElement | null)[]>([]);
245	  const gLabels = useRef<(HTMLElement | null)[]>([]);
246	  const arcsRef = useRef<THREE.Group>(null);
247	  const v = useMemo(() => ({ a: new THREE.Vector3(), b: new THREE.Vector3(), c: new THREE.Vector3(), m: new THREE.Vector3(), q: new THREE.QuadraticBezierCurve3() }), []);
248	  useFrame((_, dt) => {
249	    const a = p.anim.current;
250	    const k = (dur: number) => (p.reduced ? 1 : dt / dur);
251	    if (!p.active) { a.split = 0; a.link = 0; a.fly = 0; }          // leaving: the requirements go, the diamonds descend
252	    a.rise = toward(a.rise, p.active ? 1 : 0, k(RISE_S));
253	    // forward in order (rise → split → link / fly), backward in reverse (fly → link → split)
254	    const gSplit = p.active && defAtLeast(stage, "drafted") ? 1 : 0;
255	    const gLink = p.active && stage === "linked" ? 1 : 0;
256	    const gFly = p.active && stage === "car" ? 1 : 0;
257	    if (a.fly > gFly) a.fly = toward(a.fly, 0, k(FLY_S * 0.8));
258	    else if (a.link > gLink) a.link = toward(a.link, 0, k(0.35));
259	    else if (a.split > gSplit) a.split = toward(a.split, 0, k(SPLIT_S * 0.8));
260	    else if (a.rise >= 1 && a.split < gSplit) a.split = toward(a.split, 1, k(SPLIT_S));
261	    else if (a.split >= 1 && a.link < gLink) a.link = toward(a.link, 1, k(LINK_S));
262	    else if (a.split >= 1 && a.fly < gFly) { if (a.flyWait > 0) a.flyWait -= dt; else a.fly = toward(a.fly, 1, k(FLY_S)); }
263	    const isLanded = a.fly >= 1;
264	    if (isLanded !== landed.current) { landed.current = isLanded; p.onLanded(isLanded); }
265	
266	    const eR = easeIO(a.rise);
267	    const dShow = 1 - smooth(0.08, 0.45, a.split);
268	    const leaving = p.active ? 1 : smooth(0, 0.3, a.rise);            // the copies hand back to page 2's diamonds
269	    diamonds.forEach((d, i) => {
270	      const g = dGroups.current[i];
271	      if (!g) return;
272	      g.position.set(d.ring[0] + (d.plane[0] - d.ring[0]) * eR, d.ring[1] + (d.plane[1] - d.ring[1]) * eR, d.ring[2] + (d.plane[2] - d.ring[2]) * eR);
273	      const s = dShow * (p.active ? 1 : leaving);
274	      g.visible = s > 0.01;
275	      g.scale.setScalar(Math.max(0.001, 0.35 + 0.65 * s));
276	      const m = dMats.current[i];
277	      if (m) m.opacity = 0.9 * s;
278	      const el = dLabels.current[i];
279	      if (el) { const o = p.active ? dShow : 0; el.style.opacity = o.toFixed(3); el.style.display = o > 0.02 ? "" : "none"; }
280	    });
281	
282	    const gShow = smooth(0.6, 1, a.split) * (1 - smooth(0, 0.3, a.fly));
283	    groups.forEach((_, i) => {
284	      const el = gLabels.current[i];
285	      if (el) { el.style.opacity = gShow.toFixed(3); el.style.display = gShow > 0.02 ? "" : "none"; }
286	    });
287	    if (arcsRef.current) arcsRef.current.visible = a.link > 0.005;
288	
289	    nodes.forEach((n, i) => {
290	      const g = nGroups.current[i], el = nEls.current[i];
291	      if (!g || !el) return;
292	      const show = a.split > 0.001 && a.fly < 1;
293	      el.style.display = show ? "" : "none";
294	      if (!show) return;
295	      const dp = n.d >= 0 ? dGroups.current[n.d]?.position : null;
296	      v.a.set(...(dp ? [dp.x, dp.y, dp.z] as Vec3 : n.slot));
297	      v.b.copy(v.a).add(v.c.set(...n.burst));
298	      let scale = 1;
299	      if (a.split < 0.3) { const t = easeOut(a.split / 0.3); v.m.lerpVectors(v.a, v.b, t); scale = 0.3 + 0.7 * t; }
300	      else {
301	        const t = easeIO((a.split - 0.3) / 0.7);
302	        v.c.set(...n.slot);
303	        v.q.v0.copy(v.b); v.q.v2.copy(v.c); v.q.v1.lerpVectors(v.b, v.c, 0.5); v.q.v1.y += 0.22;
304	        v.q.getPoint(t, v.m);
305	      }
306	      if (a.fly > 0 && n.zone) {
307	        const t = easeIO(a.fly);
308	        v.q.v0.set(...n.slot); v.q.v2.set(...n.zone); v.q.v1.lerpVectors(v.q.v0, v.q.v2, 0.5); v.q.v1.y = Math.max(v.q.v0.y, v.q.v2.y) + 0.35;
309	        v.q.getPoint(t, v.m);
310	      }
311	      g.position.copy(v.m);
312	      el.style.setProperty("--s", scale.toFixed(3));
313	      el.style.setProperty("--v", (1 - smooth(0.05, 0.4, a.fly)).toFixed(3));   // targets fold away in flight
314	    });
315	  });
316	
317	  useLandedReset(p.active, landed, p.onLanded);
318	  usePlaneFlight(p.active && stage !== "car", p.reduced, p.nav);
319	
320	  /* links between requirements on this line, drawn on the plane between their slots */
321	  const slotOf = useMemo(() => new Map(nodes.map((n) => [n.r.key, n.slot])), [nodes]);
322	  const bundleKeys = useMemo(() => new Set(p.data.bundles.find((b) => b.id === bundle)?.keys ?? []), [p.data.bundles, bundle]);
323	  const passes = useCallback((r: Requirement) => !domains.length || domains.includes(r.domain), [domains]);
324	  const byKey = useMemo(() => new Map(p.reqs.map((r) => [r.key, r])), [p.reqs]);
325	  const arcs = useMemo(() => {
326	    const out: { l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint" }[] = [];
327	    for (const l of p.data.links) {
328	      const a = slotOf.get(l.a), b = slotOf.get(l.b);
329	      if (!a || !b) continue;
330	      const mine = !!selected && (l.a === selected || l.b === selected);
331	      if (linkVerdict(l) === "removed" && !mine) continue;
332	      const inBundle = bundleKeys.size > 0 && bundleKeys.has(l.a) && bundleKeys.has(l.b) && l.strength >= 2;
333	      const hovered = !!hover && (l.a === hover || l.b === hover);
334	      let level: "hot" | "warm" | "faint" | null;
335	      if (mine || inBundle) level = "hot";
336	      else if (hovered) level = "warm";
337	      else if (selected || bundleKeys.size || linkMode === "off" || (linkMode === "strong" && l.strength < 2)) level = null;
338	      else level = passes(byKey.get(l.a)!) && passes(byKey.get(l.b)!) ? "faint" : null;
339	      if (level) out.push({ l, a, b, level });
340	    }
341	    return out;
342	  }, [p.data.links, slotOf, selected, hover, bundleKeys, linkMode, passes, byKey, pendingLinks]);   // eslint-disable-line react-hooks/exhaustive-deps
343	
344	  const linked = useMemo(() => {
345	    if (!selected) return null;
346	    const s = new Set<string>([selected]);
347	    for (const l of p.data.links) if (linkVerdict(l) !== "removed") { if (l.a === selected) s.add(l.b); if (l.b === selected) s.add(l.a); }
348	    return s;
349	  }, [selected, p.data.links, pendingLinks]);   // eslint-disable-line react-hooks/exhaustive-deps
350	  const hoverArea = hover ? byKey.get(hover)?.area_key ?? null : null;
351	  const register = useCollisions();
352	  const spec = defAtLeast(stage, "specified");
353	
354	  return (
355	    <LabelCtx.Provider value={register}>
356	      {diamonds.map((d, i) => (
357	        <group key={d.a.key} ref={(g) => { dGroups.current[i] = g; }} position={d.ring}>
358	          <StageDiamond a={d.a} children_={p.reqs.filter((r) => r.area_key === d.a.key).length}
359	                        matRef={(m) => { dMats.current[i] = m; }} labelRef={(el) => { dLabels.current[i] = el; }} />
360	        </group>
361	      ))}
362	      {groups.map((g, i) => (
363	        <Html key={g.key} position={g.labelAt} center zIndexRange={[13, 11]}>
364	          <button type="button" className="dgroup" ref={(el) => { gLabels.current[i] = el; register(`g:${g.key}`, FOCUS)(el); }}
365	                  style={{ ["--c" as string]: domainColor(g.key), display: "none" }}
366	                  data-on={domains.includes(g.key) ? "" : undefined}
367	                  onPointerEnter={() => setView({ hoverDomain: g.key })} onPointerLeave={() => setView({ hoverDomain: null })}
368	                  onClick={(e) => { e.stopPropagation(); setView((s) => ({ domains: s.domains.includes(g.key) ? s.domains.filter((x) => x !== g.key) : [...s.domains, g.key] })); }}>
369	            <i aria-hidden />{g.label}<b>{g.members.length}</b>
370	          </button>
371	        </Html>
372	      ))}
373	      <group ref={arcsRef} visible={false}>
374	        {arcs.map((x) => <PlaneArc key={String(x.l.id)} {...x} anim={p.anim} label={x.level === "hot" && stage === "linked"} />)}
375	      </group>
376	      {nodes.map((n, i) => {
377	        const r = n.r;
378	        const dim = !passes(r) ? "off" : linked && !linked.has(r.key) ? "dim" : bundleKeys.size && !bundleKeys.has(r.key) ? "dim"
379	          : hoverDomain && r.domain !== hoverDomain ? "dim" : undefined;
380	        return (
381	          <group key={r.key} ref={(g) => { nGroups.current[i] = g; }}>
382	            <Html center zIndexRange={[14, 12]}>
383	              <StageNode r={r} line={p.line} spec={spec} elRef={(el) => { nEls.current[i] = el; }} register={register}
384	                         on={selected === r.key} isLinked={!!linked?.has(r.key) && selected !== r.key}
385	                         sib={!!hoverArea && hover !== r.key && r.area_key === hoverArea} hot={hoverDomain === r.domain} dim={dim} />
386	            </Html>
387	          </group>
388	        );
389	      })}
390	    </LabelCtx.Provider>
391	  );
392	}
