394	/** A stage change back from the car must hide the pins at once, before the next frame runs. */
395	function useLandedReset(active: boolean, landed: MutableRefObject<boolean>, onLanded: (l: boolean) => void) {
396	  const stage = useView((s) => s.stage);
397	  useEffect(() => {
398	    if ((!active || stage !== "car") && landed.current) { landed.current = false; onLanded(false); }
399	  }, [active, stage, landed, onLanded]);
400	}
401	
402	/* ------------------------------------------------------------------------------------------- camera */
403	const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _q = new THREE.Quaternion(), _q0 = new THREE.Quaternion();
404	/** One camera glide: the orbit centre moves straight, the view direction turns (slerp) and the distance eases, so the
405	 *  camera swings around what it looks at instead of cutting through it (a straight line can pass through the plane or
406	 *  the car when the two views face different ways). */
407	export function glide(fromP: THREE.Vector3, fromT: THREE.Vector3, toP: THREE.Vector3, toT: THREE.Vector3, e: number,
408	                      outP: THREE.Vector3, outT: THREE.Vector3) {
409	  outT.lerpVectors(fromT, toT, e);
410	  _a.subVectors(fromP, fromT); _b.subVectors(toP, toT);
411	  const d = _a.length() + (_b.length() - _a.length()) * e;
412	  _q.setFromUnitVectors(_a.normalize(), _b.normalize());
413	  _q0.identity().slerp(_q, e);
414	  outP.copy(_a).applyQuaternion(_q0).multiplyScalar(d).add(outT);
415	}
416	
417	// On arrival (and when stepping back from the car) the camera glides up to look down on the plane; it is never
418	// moved between plane stages, so the PM's own orbit stays put while stepping.
419	function usePlaneFlight(on: boolean, reduced: boolean, nav?: MutableRefObject<NavInput>) {
420	  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
421	  const camera = useThree((s) => s.camera);
422	  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
423	  const flight = useRef<{ t0: number; fromP: THREE.Vector3; fromT: THREE.Vector3; toP: THREE.Vector3; toT: THREE.Vector3; dur: number } | null>(null);
424	  const lastReset = useRef(nav?.current.reset ?? 0);
425	  const plan = () => {
426	    if (!controls) return;
427	    const pull = aspect < 1.25 ? Math.min(2.1, Math.pow(1.25 / aspect, 0.85)) : 1;
428	    const t = new THREE.Vector3(aspect > 1.25 ? -0.55 : 0, PLANE_Y + 0.15, 0);   // wide screens: clear of the top-left column
429	    const p = new THREE.Vector3(0, 0.7, 0.72).normalize().multiplyScalar(4.5 * pull).add(t);
430	    flight.current = { t0: -1, fromP: camera.position.clone(), fromT: controls.target.clone(), toP: p, toT: t, dur: reduced ? 0 : 1.4 };
431	  };
432	  useEffect(() => {
433	    if (!on || !controls) { flight.current = null; return; }
434	    plan();
435	  }, [on, controls, camera, aspect, reduced]); // eslint-disable-line react-hooks/exhaustive-deps
436	  useFrame(({ clock }) => {
437	    if (nav && nav.current.reset !== lastReset.current) { lastReset.current = nav.current.reset; if (on) plan(); }
438	    const f = flight.current;
439	    if (!f || !controls) return;
440	    if (f.t0 < 0) f.t0 = clock.elapsedTime;
441	    const k = f.dur ? Math.min(1, (clock.elapsedTime - f.t0) / f.dur) : 1;
442	    const e = easeIO(k);
443	    glide(f.fromP, f.fromT, f.toP, f.toT, e, camera.position, controls.target);
444	    controls.update();
445	    if (k >= 1) flight.current = null;
446	  });
447	}
448	
449	/* ------------------------------------------------------------------------------------------- diamond */
450	// Page 2's diamond (same colour, size and spin), with its label; hovering names how many requirements it became.
451	function StageDiamond({ a, children_, matRef, labelRef }: {
452	  a: AreaNode; children_: number; matRef: (m: THREE.MeshBasicMaterial | null) => void; labelRef: (el: HTMLElement | null) => void;
453	}) {
454	  const ref = useRef<THREE.Mesh>(null);
455	  const register = useContext(LabelCtx);
456	  useFrame((_, dt) => { if (ref.current) ref.current.rotation.y += dt * 0.4; });
457	  const size = 0.028 + Math.min(0.03, Math.sqrt(a.metrics.comments ?? 1) * 0.0012);
458	  const quality = a.kind === "quality";
459	  return (
460	    <>
461	      <mesh ref={ref}
462	            onPointerMove={(e) => { e.stopPropagation(); setView({ hoverArea: a.key, hoverPos: { x: e.nativeEvent.clientX, y: e.nativeEvent.clientY } }); }}
463	            onPointerOut={() => setView({ hoverArea: null, hoverPos: null })}>
464	        <octahedronGeometry args={[size, 0]} />
465	        <meshBasicMaterial ref={matRef} color={AREA_COLOR(a)} wireframe={a.state === "new" || quality} transparent opacity={0.9} depthWrite={false} />
466	      </mesh>
467	      {(a.metrics.comments ?? 0) > 0 && (
468	        <Html position={[0, size + 0.05, 0]} center zIndexRange={[12, 0]}>
469	          <div className="dstage-area" ref={(el) => { labelRef(el); register(`a:${a.key}`, 1e6 + (a.metrics.comments ?? 0))(el); }}>
470	            {a.title}{children_ > 0 && <b>{children_}</b>}
471	          </div>
472	        </Html>
473	      )}
474	    </>
475	  );
476	}
477	
478	/* ------------------------------------------------------------------------------------------- requirement node */
479	// (drei <Html> renders into its own React root, so the collision register comes in as a prop, not from context)
480	const StageNode = memo(function StageNode({ r, line, spec, elRef, register, on, isLinked, sib, hot, dim }: {
481	  r: Requirement; line: string; spec: boolean; elRef: (el: HTMLElement | null) => void; register: Register;
482	  on: boolean; isLinked: boolean; sib: boolean; hot: boolean; dim: string | undefined;
483	}) {
484	  const row = rowFor(r, line);
485	  const lvl = row ? row[row.recommended] : null;
486	  const gap = r.gaps.length > 0 || !!row && [row.baseline, row.threshold, row.target, row.stretch].some((l) => l?.basis === "gap");
487	  const dir = r.metric?.direction;
488	  // compact: a long unit ("mean points on a 7-point scale") stays in the inspector, the plane shows the number
489	  const unit = r.metric?.unit && r.metric.unit.length <= 6 ? r.metric.unit : undefined;
490	  const val = !lvl || lvl.basis === "gap" ? null
491	    : dir === "binary" ? "yes" : lvl.value == null ? null : `${dir === "lower" ? "≤ " : dir === "higher" ? "≥ " : ""}${fmtLevel(lvl.value, unit)}`;
492	  return (
493	    <div className="dnode" ref={elRef} style={{ display: "none" }}>
494	      <button type="button" className="dpin" data-state={r.state ?? "held"} data-on={on ? "" : undefined}
495	              data-linked={isLinked || sib || hot ? "" : undefined} data-dim={dim} style={{ ["--c" as string]: domainColor(r.domain) }}
496	              aria-label={r.title} aria-pressed={on}
497	              onPointerEnter={(e) => setView({ hover: r.key, hoverPos: { x: e.clientX, y: e.clientY } })}
498	              onPointerMove={(e) => setView({ hoverPos: { x: e.clientX, y: e.clientY } })}
499	              onPointerLeave={() => setView({ hover: null, hoverPos: null })}
500	              onClick={(e) => { e.stopPropagation(); select(on ? null : r.key); }}>
501	        <i aria-hidden />
502	      </button>
503	      {spec && (val || gap) && (
504	        <span className="dnode-val" data-dim={dim} ref={register(`n:${r.key}`, on ? FOCUS : r.evidence_count)}>
505	          {val}{gap && <b title="Open gap">?</b>}
506	        </span>
507	      )}
508	    </div>
509	  );
510	});
511	
512	/* ------------------------------------------------------------------------------------------- arcs on the plane */
513	const WIDTH: Record<number, number> = { 1: 1, 2: 1.7, 3: 2.6 };
514	const OPACITY = { hot: 0.92, warm: 0.6, faint: 0.22 };
515	function PlaneArc({ l, a, b, level, label, anim }: {
516	  l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint"; label: boolean; anim: MutableRefObject<StageAnim>;
517	}) {
518	  const { pts, apex } = useMemo(() => {
519	    const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
520	    const mid = A.clone().lerp(B, 0.5);
521	    mid.y += 0.1 + A.distanceTo(B) * 0.22;
522	    const c = new THREE.QuadraticBezierCurve3(A, mid, B);
523	    return { pts: c.getPoints(40), apex: c.getPoint(0.5) };
524	  }, [a, b]);
525	  const ref = useRef<{ material: THREE.Material & { opacity: number } } | null>(null);
526	  const base = OPACITY[level] * (l.strength >= 3 ? 1 : l.strength === 2 ? 0.9 : 0.75);
527	  useFrame(() => { const m = ref.current?.material; if (m) m.opacity = base * anim.current.link; });
528	  const dashed = isDashed(l.relation);
529	  return (
530	    <group>
531	      <Line ref={ref as never} points={pts} color={INK} lineWidth={(WIDTH[l.strength] ?? 1.4) * (level === "hot" ? 1.15 : 1)} transparent opacity={0}
532	            dashed={dashed} dashSize={0.05} gapSize={0.04} depthWrite={false} renderOrder={level === "hot" ? 6 : 4} />
533	      {label && (
534	        <Html position={apex} center zIndexRange={[13, 11]}>
535	          <div className="dlink-label" data-dashed={dashed ? "" : undefined}>{l.via}</div>
536	        </Html>
537	      )}
538	    </group>
539	  );
540	}
541	
542	export type { DefStage };
