.parrow[data-d="down"] { color: var(--ink-3); }

/* ------------------------------------------------------------------------------------------- top-left */
/* below the page switch (top centre): the readout is wider than the corner left of it */
.hud-tl.phud { top: calc(var(--edge) + 46px); gap: 14px; width: max-content; max-width: calc(100vw - 2 * var(--edge) - 460px); }
.pcontrols { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.pcontrols .dseg { flex: none; }
.preadout { margin: 0; display: flex; align-items: flex-end; gap: 22px; pointer-events: none; }
.preadout > div { display: grid; gap: 6px; }
.preadout dt { display: inline-flex; align-items: flex-end; gap: 6px; }
.preadout dd { margin: 0; }
.preadout-band .num { font-size: 34px; color: var(--ink); }
.preadout-small .num { font-size: 20px; color: var(--ink-2); }
screens/scan/scan.css:12:.hud-tl { position: fixed; top: var(--edge); left: var(--edge); z-index: 15; display: grid; gap: 18px; justify-items: start; }
screens/scan/scan.css:153:  .hud-tl { left: 16px; top: 16px; max-width: calc(100vw - 32px); gap: 12px; }
  const disagree = disagreements(data, line);
  const confirmed = targets.filter((t) => pmBand(t)).length;

  return (
    <>
      <div className="hud-tl phud">
        <dl className="preadout" aria-label={`Priorities for ${line} in ${market}`}>
          {BANDS.map((b) => (
            <div key={b} className="preadout-band">
              <dt className="label"><BandMark band={b} color="var(--ink)" size="sm" />{b}</dt>
              <dd><span className="num">{counts[b]}</span></dd>
            </div>
          ))}
          <div className="preadout-sep" aria-hidden />
          <div className="preadout-small"><dt className="label">Proposals</dt><dd><span className="num">{props.length}</span></dd></div>
          <div className="preadout-small"><dt className="label">Choose jointly</dt><dd><span className="num">{joint}</span></dd></div>
          <div className="preadout-small"><dt className="label">Blocked</dt><dd><span className="num">{blocked}</span></dd></div>
          {markets.length > 1 && <div className="preadout-small"><dt className="label">Markets disagree</dt><dd><span className="num">{disagree.size}</span></dd></div>}
        </dl>
        <p className="pnote label">{targets.length} targets · {confirmed} confirmed by the PM · weights {String(data.weights?.scheme ?? "prio-v1")} · market weight {data.labels?.market_weight ?? "stylized (Q-015)"}</p>
        <div className="pcontrols">
          <div className="dseg" role="radiogroup" aria-label="Car line">
            {lines.map((l) => <button key={l} role="radio" aria-checked={line === l} onClick={() => setView({ line: l as LineName })}>{l}</button>)}
          </div>
          <div className="dseg pmarkets" role="radiogroup" aria-label="Market">
            <span className="dseg-name label">Market</span>
            {markets.map((m) => <button key={m} role="radio" aria-checked={market === m} onClick={() => setMarket(m)} title={MARKET_NAME[m] ?? m}>{m}</button>)}
          </div>
          <div className="dseg" role="radiogroup" aria-label="View">
            <button role="radio" aria-checked={view === "skyline"} onClick={() => setP({ view: "skyline" })}>Skyline</button>
            <button role="radio" aria-checked={view === "matrix"} onClick={() => setP({ view: "matrix" })}>Matrix</button>
          </div>
        </div>
        {pd.sample && <p className="dsample" role="status"><b>Sample data</b> {pd.why}. Live priorities replace it as soon as the stage has run.</p>}
      </div>

      {view === "matrix" && <Matrix pd={pd} line={line} markets={markets} market={market} onMarket={setMarket} />}
      {showPanel && (sel ? <Inspector key={tid(sel)} pd={pd} t={sel} markets={markets} onMarket={setMarket} /> : <RankedList pd={pd} targets={targets} line={line} market={market} />)}
      <TargetHover pd={pd} line={line} market={market} />
      <Dock mode="prioritize" sel={null} guide={<PrioritizeGuide sel={sel} view={view} />} agent={<AgentPanel layer="prioritize" />} running={!!activity.data?.running} />
    </>

